                    ("مصطفى زهير مصطفى ابوسرية", "433793627", "41399", "الصف السابع", "", "", "", "سليم", "سليم", "سليم", "زهير مصطفى زهير ابوسرية", "الأب", "802636068", "0598275415", "", "0598275415", "", "", "الزيتون بالقرب من روضة الهدى", "إيجار", "تدمير كلي", "الزيتون مخيم المناصرة", "خيمة", ""),

            };

            var parentUserMap = new Dictionary<string, User>(StringComparer.OrdinalIgnoreCase);

            foreach (var rec in studentRecords)
            {
                if (string.IsNullOrWhiteSpace(rec.FullName)) continue;

                // 1. Parse Date of Birth
                DateOnly dob = new DateOnly(2012, 1, 1);
                if (!string.IsNullOrWhiteSpace(rec.Dob))
                {
                    var formats = new[] { "dd/MM/yyyy", "d/M/yyyy", "yyyy-MM-dd", "yyyy/MM/dd", "d/MM/yyyy", "dd/M/yyyy" };
                    if (DateOnly.TryParseExact(rec.Dob.Trim(), formats, CultureInfo.InvariantCulture, DateTimeStyles.None, out var parsed))
                    {
                        dob = parsed;
                    }
                }

                // 2. Manage Parent Account
                int? parentUserId = null;
                var parentIdKey = !string.IsNullOrWhiteSpace(rec.ParentIdNum) ? rec.ParentIdNum.Trim() : (!string.IsNullOrWhiteSpace(rec.ParentMobile) ? rec.ParentMobile.Trim() : null);

                if (!string.IsNullOrWhiteSpace(parentIdKey))
                {
                    if (parentUserMap.TryGetValue(parentIdKey, out var existingParentUser))
                    {
                        parentUserId = existingParentUser.Id;
                    }
                    else
                    {
                        var dbParentUser = db.Users.FirstOrDefault(u => u.Role == UserRole.Parent && u.Username == parentIdKey);
                        if (dbParentUser == null)
                        {
                            var pName = !string.IsNullOrWhiteSpace(rec.ParentName) ? rec.ParentName.Trim() : $"ولي أمر {rec.FullName.Trim()}";
                            dbParentUser = new User
                            {
                                Username = parentIdKey,
                                PasswordHash = hasher.HashPassword("123456"),
                                PlainPassword = "123456",
                                Role = UserRole.Parent,
                                FullName = pName,
                                IsActive = true
                            };
                            db.Users.Add(dbParentUser);
                            db.SaveChanges();
                        }
                        parentUserMap[parentIdKey] = dbParentUser;
                        parentUserId = dbParentUser.Id;
                    }
                }

                // 3. Create Student Entity
                var student = new Student
                {
                    FullName = rec.FullName.Trim(),
                    StudentIdentityNumber = !string.IsNullOrWhiteSpace(rec.IdNum) ? rec.IdNum.Trim() : null,
                    DateOfBirth = dob,
                    Address = !string.IsNullOrWhiteSpace(rec.CurrAddr) ? rec.CurrAddr.Trim() : (!string.IsNullOrWhiteSpace(rec.OrigAddr) ? rec.OrigAddr.Trim() : "ØºØ²Ø©"),
                    FamilyContact = !string.IsNullOrWhiteSpace(rec.ParentMobile) ? rec.ParentMobile.Trim() : (!string.IsNullOrWhiteSpace(rec.StMobile) ? rec.StMobile.Trim() : ""),
                    ParentId = parentUserId,
                    RegistrationDate = new DateOnly(2026, 8, 29),
                    IsActive = true,
                    PreviousQuranMemorization = rec.PrevMemo,
                    StudentMobile = rec.StMobile,
                    StudentWhatsapp = rec.StWhatsapp,
                    HealthStatus = rec.Health,
                    FatherStatus = rec.FatherSt,
                    MotherStatus = rec.MotherSt,
                    Kinship = rec.Kinship,
                    ParentIdentityNumber = rec.ParentIdNum,
                    WhatsappNumber = rec.ParentWhatsapp,
                    WalletNumber = rec.WalletNum,
                    BankAccountNumber = rec.BankAccount,
                    BankName = rec.BankName,
                    OriginalAddress = rec.OrigAddr,
                    OriginalHousingType = rec.OrigHType,
                    OriginalHousingStatus = rec.OrigHStat,
                    CurrentAddress = rec.CurrAddr,
                    CurrentHousingType = rec.CurrHType,
                    Notes = rec.Notes
                };

                db.Students.Add(student);
                db.SaveChanges();

                // 4. Create Student User account for student portal
                var stUsername = !string.IsNullOrWhiteSpace(rec.IdNum) ? rec.IdNum.Trim() : $"st_{student.Id}";
                if (!db.Users.Any(u => u.Username == stUsername))
                {
                    db.Users.Add(new User
                    {
                        Username = stUsername,
                        PasswordHash = hasher.HashPassword("123456"),
                        PlainPassword = "123456",
                        Role = UserRole.Student,
                        FullName = student.FullName,
                        StudentId = student.Id,
                        IsActive = true
                    });
                    db.SaveChanges();
                }
            }

            // Flush changes to SQLite file
            try
            {
                db.Database.ExecuteSqlRaw("PRAGMA wal_checkpoint(TRUNCATE);");
            }
            catch { }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"[Database] Student seed notice: {ex.Message}");
        }
    }
}